    CONSTRAINT ck_ecom_kupon_kuota CHECK (((kuota_total IS NULL) OR (kuota_total >= 0))),
    CONSTRAINT ck_ecom_kupon_nilai CHECK ((((persen IS NULL) OR (persen >= (0)::numeric)) AND ((nilai IS NULL) OR (nilai >= (0)::numeric)))),
    CONSTRAINT ck_ecom_kupon_nilai_maks CHECK (((nilai_maks IS NULL) OR (nilai_maks >= (0)::numeric))),
    CONSTRAINT ck_ecom_kupon_periode CHECK (((periode_mulai IS NULL) OR (periode_berakhir IS NULL) OR (periode_berakhir >= periode_mulai))),
    CONSTRAINT ecom_kupon_kuota_per_pelanggan_check CHECK ((kuota_per_pelanggan >= 1)),
    CONSTRAINT ecom_kupon_kuota_terpakai_check CHECK ((kuota_terpakai >= 0)),
    CONSTRAINT ecom_kupon_syarat_minimum_check CHECK ((syarat_minimum >= (0)::numeric))
);
