    ongkir numeric(18,4) DEFAULT 0 NOT NULL,
    nilai_total numeric(18,4) DEFAULT 0 NOT NULL,
    metode_bayar character varying(100),
    gateway_ref character varying(150),
    waktu_bayar timestamp with time zone,
    kedaluwarsa_bayar_at timestamp with time zone,
    status_bayar public.enum_status_bayar_ecom DEFAULT 'BELUM_BAYAR'::public.enum_status_bayar_ecom NOT NULL,
    id_core_users_verifikasi bigint,
    status_konversi public.enum_status_konversi_ecom DEFAULT 'MENUNGGU'::public.enum_status_konversi_ecom NOT NULL,
    id_sls_pesanan_penjualan bigint,
    nilai_refund numeric(18,4),
    status public.enum_status_pesanan_web_ecom DEFAULT 'MENUNGGU_PEMBAYARAN'::public.enum_status_pesanan_web_ecom NOT NULL,
    id_core_users_batal bigint,
    alasan_batal character varying(300),
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    id_ecom_member bigint,
    sesi_perangkat character varying(150),
    biaya_layanan numeric(18,4) DEFAULT 0 NOT NULL,
    poin_ditukar integer DEFAULT 0 NOT NULL,
    kalkulasi_ref character varying(150),
    opsi_ref character varying(150),
    opsi_kirim jsonb,
    id_core_files_bukti bigint,
    resi character varying(150),
    tracking_link character varying(300),
    order_kurir_ref character varying(150),
    sumber_resi public.enum_sumber_resi_ecom,
    waktu_diterima timestamp with time zone,
    nilai_dp numeric(18,4),
    id_core_files_bukti_dp bigint,
    waktu_dp_verifikasi timestamp with time zone,
    id_core_kelurahan_kirim bigint,
    kode_pos_kirim character varying(50),
    CONSTRAINT ck_ecom_pesanan_web_batal CHECK (((status <> ALL (ARRAY['DIBATALKAN'::public.enum_status_pesanan_web_ecom, 'REFUND'::public.enum_status_pesanan_web_ecom])) OR (alasan_batal IS NOT NULL))),
    CONSTRAINT ck_ecom_pesanan_web_dp CHECK (((nilai_dp IS NULL) OR ((nilai_dp >= (0)::numeric) AND (nilai_dp <= nilai_total)))),
    CONSTRAINT ck_ecom_pesanan_web_kalkulasi CHECK (((kalkulasi_ref IS NULL) = (opsi_ref IS NULL))),
    CONSTRAINT ck_ecom_pesanan_web_refund CHECK (((nilai_refund IS NULL) OR ((nilai_refund >= (0)::numeric) AND (nilai_refund <= nilai_total)))),
    CONSTRAINT ck_ecom_pesanan_web_resi CHECK (((resi IS NULL) OR (sumber_resi IS NOT NULL))),
    CONSTRAINT ecom_pesanan_web_biaya_layanan_check CHECK ((biaya_layanan >= (0)::numeric)),
    CONSTRAINT ecom_pesanan_web_diskon_kupon_check CHECK ((diskon_kupon >= (0)::numeric)),
    CONSTRAINT ecom_pesanan_web_nilai_subtotal_check CHECK ((nilai_subtotal >= (0)::numeric)),
    CONSTRAINT ecom_pesanan_web_nilai_total_check CHECK ((nilai_total >= (0)::numeric)),
    CONSTRAINT ecom_pesanan_web_ongkir_check CHECK ((ongkir >= (0)::numeric)),
    CONSTRAINT ecom_pesanan_web_poin_ditukar_check CHECK ((poin_ditukar >= 0))
);
