CREATE TABLE public.rsv_reservasi (
    id bigint NOT NULL,
    entity_id uuid DEFAULT gen_random_uuid() NOT NULL,
    nomor character varying(150) NOT NULL,
    jenis_sumber public.enum_jenis_sumber_rsv NOT NULL,
    id_rsv_jadwal_ketersediaan bigint,
    waktu_mulai timestamp with time zone NOT NULL,
    durasi_menit integer NOT NULL,
    jumlah_orang integer NOT NULL,
    id_fnb_meja bigint,
    meja_ref character varying(50),
    meja_nama character varying(100),
    id_sls_pelanggan bigint,
    nama_tamu character varying(100),
    telepon_tamu character varying(50),
    kanal public.enum_kanal_reservasi_rsv DEFAULT 'MANUAL'::public.enum_kanal_reservasi_rsv NOT NULL,
    status public.enum_status_reservasi_rsv DEFAULT 'DRAFT'::public.enum_status_reservasi_rsv NOT NULL,
    status_deposit public.enum_status_deposit_rsv DEFAULT 'TIDAK_PERLU'::public.enum_status_deposit_rsv NOT NULL,
    nilai_deposit numeric(18,4),
    overbook_disetujui boolean DEFAULT false NOT NULL,
    id_core_users_setuju_overbook bigint,
    ref_web character varying(150),
    alasan_batal character varying(300),
    konfirmasi_at timestamp with time zone,
    checkin_at timestamp with time zone,
    selesai_at timestamp with time zone,
    batal_at timestamp with time zone,
    catatan character varying(300),
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT ck_rsv_reservasi_identitas CHECK (((id_sls_pelanggan IS NOT NULL) OR (nama_tamu IS NOT NULL))),
    CONSTRAINT ck_rsv_reservasi_meja_hanya_meja CHECK ((((id_fnb_meja IS NULL) OR (jenis_sumber = 'MEJA'::public.enum_jenis_sumber_rsv)) AND ((meja_ref IS NULL) OR (jenis_sumber = 'MEJA'::public.enum_jenis_sumber_rsv)))),
    CONSTRAINT ck_rsv_reservasi_nilai_deposit CHECK (((nilai_deposit IS NULL) OR (nilai_deposit >= (0)::numeric))),
    CONSTRAINT ck_rsv_reservasi_overbook_aktor CHECK (((overbook_disetujui = false) OR (id_core_users_setuju_overbook IS NOT NULL))),
    CONSTRAINT ck_rsv_reservasi_selesai_setelah_checkin CHECK (((selesai_at IS NULL) OR (checkin_at IS NULL) OR (selesai_at >= checkin_at))),
    CONSTRAINT rsv_reservasi_durasi_menit_check CHECK ((durasi_menit > 0)),
    CONSTRAINT rsv_reservasi_jumlah_orang_check CHECK ((jumlah_orang > 0))
);
