    CONSTRAINT ck_sls_promosi_aturan_target CHECK ((((jenis_target = 'PRODUK'::public.enum_jenis_target_aturan_sls) AND (id_inv_produk IS NOT NULL) AND (id_inv_kategori_produk IS NULL)) OR ((jenis_target = 'KATEGORI'::public.enum_jenis_target_aturan_sls) AND (id_inv_kategori_produk IS NOT NULL) AND (id_inv_produk IS NULL)) OR ((jenis_target = 'SEMUA'::public.enum_jenis_target_aturan_sls) AND (id_inv_produk IS NULL) AND (id_inv_kategori_produk IS NULL))))
);
